    }

    override fun writeValue(
        stream: ByteArrayOutputStream,
        value: Any?,
    ) {
        when (value) {
            is VideoDeviceKind -> {
                stream.write(129)
                writeValue(stream, value.raw.toLong())
            }
            is AudioDeviceKind -> {
                stream.write(130)
                writeValue(stream, value.raw.toLong())
            }
            is NativePipelineState -> {
                stream.write(131)
                writeValue(stream, value.raw.toLong())
            }
            is GazerErrorCode -> {
                stream.write(132)
                writeValue(stream, value.raw.toLong())
            }
            is OutputOrientation -> {
                stream.write(133)
                writeValue(stream, value.raw.toLong())
            }
            is VideoDevice -> {
                stream.write(134)
                writeValue(stream, value.toList())
            }
            is AudioDevice -> {
                stream.write(135)
                writeValue(stream, value.toList())
            }
            is StreamConfig -> {
                stream.write(136)
                writeValue(stream, value.toList())
            }
            is StreamTarget -> {
                stream.write(137)
                writeValue(stream, value.toList())
            }
            is PrepareResult -> {
                stream.write(138)
                writeValue(stream, value.toList())
            }
            is StatsSample -> {
                stream.write(139)
                writeValue(stream, value.toList())
            }
            is StateEvent -> {
                stream.write(140)
                writeValue(stream, value.toList())
            }
            else -> super.writeValue(stream, value)
        }
    }
}

